<script>
const search=document.getElementById('route-search');const routes=[...document.querySelectorAll('.route')];const groups=[...document.querySelectorAll('.group')];const count=document.getElementById('result-count');const empty=document.getElementById('no-results');
function filterRoutes(){const query=search.value.trim().toLowerCase();let visible=0;routes.forEach(route=>{const match=!query||route.dataset.search.includes(query);route.style.display=match?'grid':'none';if(match)visible++});groups.forEach(group=>{const has=[...group.querySelectorAll('.route')].some(route=>route.style.display!=='none');group.style.display=has?'block':'none'});empty.style.display=visible?'none':'block';count.textContent=visible+' module'+(visible===1?'':'s')+' visible'}search.addEventListener('input',filterRoutes);
</script>
<script>document.documentElement.dataset.theme=['window-blue','deep-space-blue'].includes(localStorage.getItem('sgw_theme'))?localStorage.getItem('sgw_theme'):'default-white';</script></body>
